//! Read-path parity against the SAGE mutation oracle
//! (`tests/fixtures/oracle-mutations/{graph-retrieval,audience}.json`,
//! generated by `scripts/oracle/build-mutation-fixtures.ts` from the real
//! SAGE code at the baseline commit).
//!
//! Each scenario's `rememberSage` steps are replayed on a fresh managed
//! store; every read call is then compared with the oracle:
//! * `retrieveForPath`, `findRelatedSage`, `retrieveForAudience`,
//!   `searchSage`: returned ids in order;
//! * `listSagePage`: ids per page, `total`, `statusCounts`, cursor presence;
//! * `graphFor`, `traverseGraph`: the edge set as (from, to, relation);
//! * `getStats`: `byStatus` and `byKind`;
//! * `retrieveForAudience`: also the `memory.audience_truncated` audit row.
//!
//! Not compared (documented):
//! * `getStats.edges`: WrongMemory counts only edges owned by a memory
//!   the viewer can see (WM-603), not the baseline's raw edge count.
//! * `searchSageWithBreakdown`, the pure rerank note: no vector channel
//!   (see docs/status.md, WM-405).
//! * `findMemoriesForFile`: compared bucket by bucket (ids, via, strength,
//!   supersession head, pending review) plus the counts.
//! * `searchSage` with `semanticRerank=false`: no semantic provider is
//!   configured on either side, so it equals the default call; compared
//!   the same way.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use rusqlite::Connection;
use serde_json::{Value, json};
use wrongmemory_contracts::{MemorySource, RememberParams};
use wrongmemory_storage::retrieval::PathOptions;
use wrongmemory_storage::{MutationCtx, SageStore, Viewer};

fn fixture(name: &str) -> Value {
    let p = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/oracle-mutations")
        .join(format!("{name}.json"));
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

struct Replay {
    _tmp: tempfile::TempDir,
    root: PathBuf,
    db: PathBuf,
    store: SageStore,
    ids: BTreeMap<String, String>,
    audit_mark: i64,
}

impl Replay {
    fn new(files: &[&str]) -> Self {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("project");
        for f in files {
            let p = root.join(f);
            std::fs::create_dir_all(p.parent().unwrap()).unwrap();
            std::fs::write(p, "x\n").unwrap();
        }
        std::fs::create_dir_all(&root).unwrap();
        let db = tmp.path().join("store").join("sage.db");
        SageStore::create_managed(&db, "2026-11-01T00:00:00.000Z").unwrap();
        let (store, _) =
            SageStore::open(&db, true, Some(root.clone()), "2026-11-01T00:00:00.000Z").unwrap();
        Self {
            _tmp: tmp,
            root,
            db,
            store,
            ids: BTreeMap::new(),
            audit_mark: 0,
        }
    }

    fn label(id: &str) -> String {
        let id = id.strip_prefix("mem_").unwrap_or(id);
        id.strip_prefix("<id:")
            .and_then(|s| s.strip_suffix('>'))
            .map(str::to_string)
            .unwrap_or_else(|| id.to_string())
    }

    fn real(&self, fixture_id: &str) -> String {
        let l = Self::label(fixture_id);
        self.ids.get(&l).cloned().unwrap_or(l)
    }

    fn label_of(&self, real: &str) -> String {
        self.ids
            .iter()
            .find(|(_, v)| *v == real)
            .map(|(k, _)| k.clone())
            .unwrap_or_else(|| real.to_string())
    }

    /// Graph node with any memory id replaced by its label.
    fn node_of(&self, node: &str, fixture: bool) -> String {
        match node.strip_prefix("mem:") {
            Some(id) if fixture => format!("mem:{}", Self::label(id)),
            Some(id) => format!("mem:{}", self.label_of(id)),
            None => node.to_string(),
        }
    }

    fn new_audit(&mut self) -> Vec<(String, Value)> {
        let c = Connection::open(&self.db).unwrap();
        let rows: Vec<(i64, String, String)> = c
            .prepare("SELECT id, event, data FROM audit_log WHERE id > ?1 ORDER BY id")
            .unwrap()
            .query_map([self.audit_mark], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
            .unwrap()
            .collect::<Result<_, _>>()
            .unwrap();
        if let Some((last, ..)) = rows.last() {
            self.audit_mark = *last;
        }
        rows.into_iter()
            .map(|(_, e, d)| (e, serde_json::from_str(&d).unwrap()))
            .collect()
    }

    fn remember(&mut self, st: &Value, now: &str) {
        let input = &st["call"]["input"];
        let mut inp = input.clone();
        for k in ["supersedes", "contradicts"] {
            if let Some(a) = inp.get(k).cloned() {
                inp[k] = json!(
                    a.as_array()
                        .unwrap()
                        .iter()
                        .map(|x| self.real(x.as_str().unwrap()))
                        .collect::<Vec<_>>()
                );
            }
        }
        let owner = inp["ownerSessionId"].as_str().map(str::to_string);
        inp.as_object_mut().unwrap().remove("ownerSessionId");
        let mut p: RememberParams = serde_json::from_value(inp).unwrap();
        if p.sources.is_empty() {
            p.sources = vec![MemorySource {
                kind: "user".into(),
                ..Default::default()
            }];
        }
        let ctx = MutationCtx {
            principal_id: "host".into(),
            client_label: "oracle-replay".into(),
            session_id: owner,
            idempotency_key: None,
            now_iso: now.into(),
        };
        let out = self.store.remember(&p, &ctx).unwrap();
        let label = Self::label(st["result"]["id"].as_str().unwrap());
        self.ids.insert(label, out.id);
    }

    fn ids_of(&self, records: impl IntoIterator<Item = String>) -> Vec<String> {
        records.into_iter().map(|id| self.label_of(&id)).collect()
    }
}

fn fixture_ids(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|m| Replay::label(m["id"].as_str().unwrap()))
        .collect()
}

fn viewer(session: Option<&str>) -> Viewer {
    Viewer {
        session_id: session.map(str::to_string),
    }
}

/// Oracle clock: one tick per step from the fixture epoch.
fn clock(step_index: usize) -> String {
    format!(
        "2026-11-01T00:{:02}:{:02}.000Z",
        (step_index + 1) / 60,
        (step_index + 1) % 60
    )
}

fn replay(name: &str, files: &[&str]) -> Vec<String> {
    let f = fixture(name);
    let mut r = Replay::new(files);
    let mut diffs = Vec::new();
    for (i, st) in f["steps"].as_array().unwrap().iter().enumerate() {
        let step = st["step"].as_str().unwrap_or("");
        let Some(method) = st["call"]["method"].as_str() else {
            continue;
        };
        let input = &st["call"]["input"];
        let want = &st["result"];
        let now = clock(i);
        let v = viewer(input["sessionId"].as_str());
        let mut cmp = |what: &str, want: Value, got: Value| {
            if want != got {
                diffs.push(format!("{step}: {what}\n  oracle={want}\n  ours  ={got}"));
            }
        };
        match method {
            "rememberSage" => r.remember(st, &now),
            "dump" => {}
            "retrieveForPath" => {
                let paths: Vec<String> = input["paths"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| {
                        p.as_str()
                            .unwrap()
                            .replace("<root>", &r.root.to_string_lossy())
                    })
                    .collect();
                let opts = PathOptions {
                    include_ancestors: input["includeAncestors"].as_bool(),
                    include_audience_scoped: input["includeAudienceScoped"].as_bool(),
                    ..Default::default()
                };
                let got = r.store.retrieve_for_paths(&paths, &opts, &v).unwrap();
                let got = r.ids_of(got.hits.into_iter().map(|h| h.memory.id));
                cmp("ids", json!(fixture_ids(want)), json!(got));
            }
            "findRelatedSage" => {
                let ids: Vec<String> = input["ids"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|x| r.real(x.as_str().unwrap()))
                    .collect();
                // Baseline defaults: limit DEFAULT_LIST_LIMIT, maxDepth 3.
                let got = r.store.find_related(&ids, 20, 3, &v).unwrap();
                let got = r.ids_of(got.into_iter().map(|h| h.memory.id));
                cmp("ids", json!(fixture_ids(want)), json!(got));
            }
            "graphFor" | "traverseGraph" => {
                let edges: Vec<(String, String, String)> = if method == "graphFor" {
                    let q = input["query"].as_str().unwrap();
                    let q = if q.starts_with("<id:") {
                        r.real(q)
                    } else {
                        q.to_string()
                    };
                    let g = r.store.graph_for(&q, 2, 100, &v).unwrap();
                    g.edges
                        .into_iter()
                        .map(|e| (e.from, e.to, e.relation))
                        .collect()
                } else {
                    let from = input["from"].as_str().unwrap();
                    let start = format!("mem:{}", r.real(from.strip_prefix("mem:").unwrap()));
                    let (edges, _) = r.store.traverse(&[start], 2, 100, &v).unwrap();
                    edges
                        .into_iter()
                        .map(|e| (e.from, e.to, e.relation))
                        .collect()
                };
                let got: BTreeSet<String> = edges
                    .iter()
                    .map(|(f, t, rel)| {
                        format!("{} -{rel}-> {}", r.node_of(f, false), r.node_of(t, false))
                    })
                    .collect();
                let exp: BTreeSet<String> = want
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|e| {
                        format!(
                            "{} -{}-> {}",
                            r.node_of(e["from"].as_str().unwrap(), true),
                            e["relation"].as_str().unwrap(),
                            r.node_of(e["to"].as_str().unwrap(), true)
                        )
                    })
                    .collect();
                cmp("edges", json!(exp), json!(got));
            }
            "retrieveForAudience" => {
                let limit = input["limit"].as_i64();
                // The graph scenario records the context itself as input.
                let context = input.get("context").unwrap_or(input);
                let got = r
                    .store
                    .retrieve_for_audience(context, limit, &v, &now)
                    .unwrap();
                let got_ids = r.ids_of(got.memories.into_iter().map(|m| m.id));
                cmp("ids", json!(fixture_ids(want)), json!(got_ids));
                let want_audit: Vec<Value> = st["state"]["auditEvents"]
                    .as_array()
                    .map(|a| a.iter().map(|e| json!([e["event"], e["data"]])).collect())
                    .unwrap_or_default();
                let got_audit: Vec<Value> = r
                    .new_audit()
                    .into_iter()
                    .map(|(e, d)| json!([e, d]))
                    .collect();
                // Steps recorded without state carry no audit expectation.
                if st.get("state").is_some() {
                    cmp("audit", json!(want_audit), json!(got_audit));
                }
            }
            "searchSage" => {
                let q = input["query"].as_str().unwrap();
                let got = r.store.search(q, 20, None, None, &v).unwrap();
                let got = r.ids_of(got.hits.into_iter().map(|h| h.memory.id));
                cmp("ids", json!(fixture_ids(want)), json!(got));
            }
            "listSagePage" => {
                // Cursors are compared by presence; ours encode real ids.
                let cursor = input["cursor"].as_str().map(|c| {
                    if c == "not-a-cursor" {
                        c.to_string()
                    } else {
                        // Continue from our own previous page.
                        r.ids.get("__cursor").cloned().unwrap_or_default()
                    }
                });
                let limit = input["limit"].as_u64().map(|l| l as usize);
                let page = r
                    .store
                    .list_page(
                        None,
                        None,
                        input["query"].as_str(),
                        limit,
                        cursor.as_deref(),
                        &v,
                    )
                    .unwrap();
                let pv = serde_json::to_value(&page).unwrap();
                let got_ids = r.ids_of(
                    pv["memories"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|m| m["id"].as_str().unwrap().to_string()),
                );
                cmp("ids", json!(fixture_ids(&want["memories"])), json!(got_ids));
                cmp("total", want["total"].clone(), pv["total"].clone());
                cmp(
                    "statusCounts",
                    want["statusCounts"].clone(),
                    pv["statusCounts"].clone(),
                );
                cmp(
                    "hasNextCursor",
                    json!(want["nextCursor"].is_string()),
                    json!(pv["nextCursor"].is_string()),
                );
                match pv["nextCursor"].as_str() {
                    Some(c) => {
                        r.ids.insert("__cursor".into(), c.to_string());
                    }
                    None => {
                        r.ids.remove("__cursor");
                    }
                }
            }
            "getStats" => {
                let got = r.store.stats(&v).unwrap();
                let nonzero = |m: &Value| -> Value {
                    Value::Object(
                        m.as_object()
                            .unwrap()
                            .iter()
                            .filter(|(_, n)| n.as_i64() != Some(0))
                            .map(|(k, n)| (k.clone(), n.clone()))
                            .collect(),
                    )
                };
                cmp(
                    "byStatus",
                    nonzero(&want["byStatus"]),
                    nonzero(&got["byStatus"]),
                );
                cmp("byKind", nonzero(&want["byKind"]), nonzero(&got["byKind"]));
            }
            "findMemoriesForFile" => {
                let q = wrongmemory_storage::find_file::FileQuery::default();
                let got = r
                    .store
                    .find_memories_for_file(input["path"].as_str().unwrap(), &q, &v, &now)
                    .unwrap();
                let shape = |res: &Value, fixture: bool| -> Value {
                    let bucket = |k: &str| -> Value {
                        Value::Array(
                            res[k]
                                .as_array()
                                .unwrap()
                                .iter()
                                .map(|e| {
                                    let id = e["memory"]["id"].as_str().unwrap();
                                    let head = e["supersededByActiveId"].as_str();
                                    let lbl = |x: &str| {
                                        if fixture {
                                            Replay::label(x)
                                        } else {
                                            r.label_of(x)
                                        }
                                    };
                                    json!([
                                        lbl(id),
                                        e["matchedVia"],
                                        e["matchStrength"],
                                        head.map(lbl),
                                        e.get("pendingReview").is_some()
                                    ])
                                })
                                .collect(),
                        )
                    };
                    json!({
                        "filePath": res["filePath"],
                        "primary": bucket("primaryMatches"),
                        "symbol": bucket("symbolMatches"),
                        "related": bucket("relatedMatches"),
                        "counts": [res["totalCount"], res["activeCount"],
                                   res["supersededCount"], res["reviewPendingCount"]],
                    })
                };
                cmp("findMemoriesForFile", shape(want, true), shape(&got, false));
            }
            // Not exposed by the daemon; see module docs.
            "searchSageWithBreakdown" => {}
            other => panic!("unhandled oracle method {other}"),
        }
    }
    diffs
}

fn assert_clean(diffs: Vec<String>) {
    assert!(
        diffs.is_empty(),
        "oracle differences:\n{}",
        diffs.join("\n")
    );
}

#[test]
fn graph_retrieval_reads_match_oracle() {
    assert_clean(replay(
        "graph-retrieval",
        &[
            "src/server/http.ts",
            "src/server/routes.ts",
            "src/lib/util.ts",
        ],
    ));
}

#[test]
fn audience_retrieval_matches_oracle() {
    assert_clean(replay("audience", &[]));
}

/// `unifiedSearchService` against the oracle (`unified-search.json`): per
/// call the hit and suggestion ids in order with score, bm25 and match
/// reason; `totalCandidates`, `rankingApplied`, `queryEcho`,
/// `matchChannel`; the decoded `nextCursor` (binding hash, ranking, channel
/// and anchor tuple); and refusals. Recorded cursors are re-encoded with the
/// replay's ids, so a walk follows exactly the oracle's positions.
#[test]
fn unified_search_matches_oracle() {
    let f = fixture("unified-search");
    let mut r = Replay::new(&["src/server/http.ts", "src/server/routes.ts"]);
    let mut diffs = Vec::new();
    let mut now = String::new();
    let close = |a: &Value, b: &Value| match (a.as_f64(), b.as_f64()) {
        (Some(x), Some(y)) => (x - y).abs() <= 1e-9 * x.abs().max(1.0),
        _ => a == b,
    };
    for st in f["steps"].as_array().unwrap() {
        let step = st["step"].as_str().unwrap_or("");
        let Some(method) = st["call"]["method"].as_str() else {
            continue;
        };
        let input = &st["call"]["input"];
        match method {
            "rememberSage" => {
                now = st["result"]["createdAt"].as_str().unwrap().to_string();
                r.remember(st, &now);
                continue;
            }
            "updateSage" => {
                now = bump(&now);
                let id = r.real(input["id"].as_str().unwrap());
                let mut patch = input.as_object().unwrap().clone();
                patch.remove("id");
                let ctx = wrongmemory_storage::MutationCtx {
                    principal_id: "host".into(),
                    client_label: "oracle-replay".into(),
                    session_id: None,
                    idempotency_key: None,
                    now_iso: now.clone(),
                };
                r.store.update(&id, &patch, &ctx, false).unwrap();
                continue;
            }
            "dump" => {
                now = bump(&now);
                continue;
            }
            "unifiedSearchService" => now = bump(&now),
            other => panic!("unhandled oracle method {other}"),
        }
        let mut query = input["query"].clone();
        if let Some(c) = query["cursor"].as_str() {
            query["cursor"] = json!(reencode_cursor(&r, c));
        }
        let options = input.get("options").cloned().unwrap_or(json!({}));
        let v = viewer(options["sessionId"].as_str());
        let got = r.store.unified_search(&query, &options, &v, &now);
        let want = &st["result"];
        match (st.get("error"), got) {
            (Some(_), Err(_)) => continue,
            (Some(e), Ok(g)) => {
                diffs.push(format!(
                    "{step}: oracle refused ({}), ours returned {g}",
                    e["message"]
                ));
                continue;
            }
            (None, Err(e)) => {
                diffs.push(format!("{step}: ours refused: {}", e.message));
                continue;
            }
            (None, Ok(got)) => {
                for list in ["hits", "suggestions"] {
                    let w = want[list].as_array().unwrap();
                    let g = got[list].as_array().unwrap();
                    let wid: Vec<String> = w
                        .iter()
                        .map(|h| Replay::label(h["id"].as_str().unwrap()))
                        .collect();
                    let gid: Vec<String> = g
                        .iter()
                        .map(|h| r.label_of(h["id"].as_str().unwrap()))
                        .collect();
                    if wid != gid {
                        diffs.push(format!("{step}: {list} oracle={wid:?} ours={gid:?}"));
                        continue;
                    }
                    for (a, b) in w.iter().zip(g) {
                        for k in [
                            "score",
                            "bm25",
                            "matchReason",
                            "kind",
                            "scope",
                            "status",
                            "importance",
                        ] {
                            if !close(&a[k], &b[k]) {
                                diffs.push(format!(
                                    "{step}: {list} {} {k} oracle={} ours={}",
                                    Replay::label(a["id"].as_str().unwrap()),
                                    a[k],
                                    b[k]
                                ));
                            }
                        }
                    }
                }
                for k in [
                    "totalCandidates",
                    "rankingApplied",
                    "queryEcho",
                    "matchChannel",
                ] {
                    if want[k] != got[k] {
                        diffs.push(format!("{step}: {k} oracle={} ours={}", want[k], got[k]));
                    }
                }
                let wc = want["nextCursor"].as_str().map(fixture_cursor);
                let gc = got["nextCursor"].as_str().map(|c| our_cursor(&r, c));
                let same = match (&wc, &gc) {
                    (Some(a), Some(b)) => {
                        a.as_object().unwrap().iter().all(|(k, v)| close(v, &b[k]))
                            && a.as_object().unwrap().len() == b.as_object().unwrap().len()
                    }
                    (None, None) => true,
                    _ => false,
                };
                if !same {
                    diffs.push(format!("{step}: nextCursor oracle={wc:?} ours={gc:?}"));
                }
            }
        }
    }
    assert_clean(diffs);
}

fn bump(iso: &str) -> String {
    let ms = wrongmemory_storage::text::parse_iso_ms(iso).unwrap() + 1000;
    let secs = ms.div_euclid(1000);
    let millis = ms.rem_euclid(1000);
    let days = secs.div_euclid(86_400);
    let tod = secs.rem_euclid(86_400);
    // Civil-from-days (Howard Hinnant).
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    format!(
        "{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}.{millis:03}Z",
        tod / 3600,
        (tod % 3600) / 60,
        tod % 60
    )
}

/// `<cursor:{...}>` from the fixture: the decoded payload with labels.
fn fixture_cursor(c: &str) -> Value {
    let inner = c
        .strip_prefix("<cursor:")
        .and_then(|s| s.strip_suffix('>'))
        .unwrap();
    let mut v: Value = serde_json::from_str(inner).unwrap();
    v["i"] = json!(Replay::label(v["i"].as_str().unwrap()));
    v
}

fn our_cursor(r: &Replay, token: &str) -> Value {
    let bytes = wrongmemory_storage::retrieval::base64url_decode(token).unwrap();
    let mut v: Value = serde_json::from_slice(&bytes).unwrap();
    v["i"] = json!(r.label_of(v["i"].as_str().unwrap()));
    v
}

fn reencode_cursor(r: &Replay, c: &str) -> String {
    let Some(inner) = c.strip_prefix("<cursor:").and_then(|s| s.strip_suffix('>')) else {
        return c.to_string(); // a deliberately malformed token
    };
    let mut v: Value = serde_json::from_str(inner).unwrap();
    v["i"] = json!(r.real(v["i"].as_str().unwrap()));
    wrongmemory_storage::retrieval::base64url_encode(v.to_string().as_bytes())
}
